{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 explicitly states that PostgreSQL transaction IDs have a limited size of 32 bits.",
      "citations": [
        {
          "index": 0,
          "quote": "But since transaction IDs have limited size (32 bits)"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 says transaction IDs are 32 bits and that running for more than 4 billion transactions causes wraparound, which entails that the XID space contains about 4 billion values.",
      "citations": [
        {
          "index": 0,
          "quote": "But since transaction IDs have limited size (32 bits) a cluster that runs for a long time (more than 4 billion transactions) would suffer transaction ID wraparound"
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 directly states that for every normal XID there are two billion older and two billion newer XIDs.",
      "citations": [
        {
          "index": 1,
          "quote": "This means that for every normal XID, there are two billion XIDs that are “older” and two billion that are “newer”"
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states that every table in every database must be vacuumed at least once every two billion transactions.",
      "citations": [
        {
          "index": 0,
          "quote": "To avoid this, it is necessary to vacuum every table in every database at least once every two billion transactions."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 0 says the data is still present, and passage 7 says a manual VACUUM should fix the problem, so the described loss is not permanent and unrecoverable.",
      "citations": [
        {
          "index": 0,
          "quote": "Actually the data is still there, but that's cold comfort if you cannot get at it."
        },
        {
          "index": 7,
          "quote": "A manual VACUUM should fix the problem"
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 says anti-wraparound autovacuum is invoked when tables may contain unfrozen rows with XIDs older than autovacuum_freeze_max_age. Passage 5 gives the default as 200 million transactions, and passage 1 describes a two-billion-transaction visibility window, so 200 million is about 10% of that window.",
      "citations": [
        {
          "index": 2,
          "quote": "autovacuum is invoked on any table that might contain unfrozen rows with XIDs older than the age specified by the configuration parameter autovacuum_freeze_max_age."
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        },
        {
          "index": 1,
          "quote": "the row version will appear to be “in the past” for the next two billion transactions"
        }
      ]
    },
    {
      "claim_id": "c7",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 caps vacuum_freeze_table_age at 0.95 times autovacuum_freeze_max_age. With the default autovacuum_freeze_max_age of 200 million, that maximum is 190 million, not 180 million.",
      "citations": [
        {
          "index": 4,
          "quote": "The effective maximum for vacuum_freeze_table_age is 0.95 * autovacuum_freeze_max_age; a setting higher than that will be capped to the maximum."
        },
        {
          "index": 5,
          "quote": "The default, 200 million transactions"
        }
      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says warnings begin when the oldest XIDs are forty million transactions from wraparound, and passage 7 says new XIDs are refused when fewer than three million transactions remain, making the interval 37 million transactions.",
      "citations": [
        {
          "index": 6,
          "quote": "when the database's oldest XIDs reach forty million transactions from the wraparound point"
        },
        {
          "index": 7,
          "quote": "the system will refuse to assign new XIDs once there are fewer than three million transactions left until wraparound"
        }
      ]
    },
    {
      "claim_id": "c9",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 8 states that once new XID assignment stops, only read-only transactions can still be started, so not all new transactions are impossible.",
      "citations": [
        {
          "index": 8,
          "quote": "In this condition any transactions already in progress can continue, but only read-only transactions can be started."
        }
      ]
    }
  ]
}

